          'assert tem(saida, "Nome: Ana Lima", "Idade: 30 anos", "Recife", "Analista")\nassert tem(executar("Leo", "Melo", "17/11/2000", "Natal", "Dev"), "Idade: 25 anos"), "Desconte 1 ano se ainda não fez aniversário neste ano"',
